  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec4 color;
in vec2 uv0;
layout(std140) uniform RainbowConstants {
  vec4 rbSize;
  vec4 rbParams;
};
float sdRound (vec2 p, vec2 b, float r) { vec2 q = abs(p) - b + r; return length(max(q, 0.0)) + min(max(q.x, q.y), 0.0) - r; }
vec3 hue (float t) {
  vec3 c0 = vec3(1.0, 0.302, 0.427), c1 = vec3(1.0, 0.694, 0.231), c2 = vec3(1.0, 0.953, 0.361), c3 = vec3(0.365, 1.0, 0.478);
  vec3 c4 = vec3(0.231, 0.906, 1.0), c5 = vec3(0.357, 0.486, 1.0), c6 = vec3(0.831, 0.357, 1.0);
  float s = fract(t) * 7.0;
  if (s < 1.0) return mix(c0, c1, s);
  if (s < 2.0) return mix(c1, c2, s - 1.0);
  if (s < 3.0) return mix(c2, c3, s - 2.0);
  if (s < 4.0) return mix(c3, c4, s - 3.0);
  if (s < 5.0) return mix(c4, c5, s - 4.0);
  if (s < 6.0) return mix(c5, c6, s - 5.0);
  return mix(c6, c0, s - 6.0);
