  vec2 p = (uv0 - 0.5) * rbSize.xy;
  p.y = -p.y;
  vec2 hb = rbSize.xy * 0.5 - rbParams.z;
  float d = sdRound(p, hb, rbSize.z);
  float dg = sdRound(p, hb + rbSize.w, rbSize.z + rbSize.w);
  float ang = atan(p.x, p.y) / 6.2831853 - cc_time.x / 2.2;
  vec3 c = hue(ang);
  float solid = 1.0 - smoothstep(-0.7, 0.7, d);
  float glow = 1.0 - smoothstep(-1.6 * rbParams.y, 1.6 * rbParams.y, dg);
  float a = max(solid, glow * 0.9) * color.a;
  return vec4(c, a);
}
layout(location = 0) out vec4 cc_FragColor;
void main() { cc_FragColor = frag(); }

